parameters.jsCode:
const busy = $input.all().map(i => i.json).filter(e => e.start && e.start.dateTime).map(e => [DateTime.fromISO(e.start.dateTime), DateTime.fromISO(e.end.dateTime)]);
const slots = [];
let day = $now.plus({ days: 1 }).startOf("day");
const stop = $now.plus({ days: 10 });
while (slots.length < 3 && day < stop) {
  if (day.weekday <= 5) {
    for (const h of [10, 11, 14, 15, 16]) {
      const s = day.set({ hour: h });
      const e = s.plus({ minutes: 30 });
      if (!busy.some(([bs, be]) => s < be && e > bs)) { slots.push(s); break; }
    }
  }
  day = day.plus({ days: 1 });
}
const text = slots.map(s => s.toFormat("cccc d LLL, h:mm a")).join("\n- ");
return $("Route by Qualification").all(0).map(l => ({ json: { ...l.json, suggested_times: text ? "- " + text : "" } }));

